CREATE TABLE IF NOT EXISTS gis_phase346_crosswalk_audit (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version TEXT NOT NULL, candidate_id UUID NOT NULL, source_feature_id UUID NOT NULL, target_feature_id UUID NOT NULL, source_type TEXT, target_type TEXT, source_minx DOUBLE PRECISION, source_maxx DOUBLE PRECISION, source_miny DOUBLE PRECISION, source_maxy DOUBLE PRECISION, target_minx DOUBLE PRECISION, target_maxx DOUBLE PRECISION, target_miny DOUBLE PRECISION, target_maxy DOUBLE PRECISION, source_state_code TEXT, target_state_code TEXT, same_state BOOLEAN, same_feature BOOLEAN, same_dataset BOOLEAN, geometry_overlap_bbox BOOLEAN, audit_status TEXT NOT NULL, issues JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,candidate_id));